import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"Console TUI wave 2 review","description":"","frontmatter":{},"headers":[],"relativePath":"research/console-tui/review-wave2.md","filePath":"research/console-tui/review-wave2.md"}`),a={name:`research/console-tui/review-wave2.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div><h1 id="console-tui-wave-2-review" tabindex="-1">Console TUI wave 2 review <a class="header-anchor" href="#console-tui-wave-2-review" aria-label="Permalink to “Console TUI wave 2 review”">​</a></h1><p>Reviewed the committed state at <code>95bb07e01b</code> for <code>packages/server/src/{Server.ts,cli/Cli.ts,host/**}</code>, <code>packages/prismarine/src/console/**</code>, the remote console wiring in <code>packages/prismarine/src/Server.ts</code>, <code>packages/console/src/{app/**,startConsole.ts,help/**}</code>, and the four changesets added since <code>1990d875c3</code>. Judged against <code>plan.md</code>, the judge amendments in <code>votes/judge-2.md</code> and <code>votes/judge-3.md</code>, <code>AGENTS.md</code>, and <code>docs/guide/versioning.md</code>. Findings already queued in <code>review-wave1.md</code> are not repeated.</p><p>Working tree at review time: <code>packages/server/src/Server.ts</code> and <code>packages/server/src/host/frontends.ts</code> are modified and <code>packages/server/src/host/frontends.test.ts</code> is untracked (another agent&#39;s work in progress). At <code>HEAD</code>, <code>loadTuiFrontend</code> is a stub returning <code>undefined</code>, so the TUI path is inert and a <code>tui</code> decision falls through to the in-process line console; the working tree replaces the stub with the lazy <code>import(&#39;@jsprismarine/console&#39;)</code> and passes <code>historyFile</code> through <code>dataPath</code>. Everything below is about <code>HEAD</code>.</p><h2 id="checks-run" tabindex="-1">Checks run <a class="header-anchor" href="#checks-run" aria-label="Permalink to “Checks run”">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td><code>pnpm exec biome lint &lt;scope&gt;</code></td><td>71 files, no diagnostics (same pre-existing 2.6.2 vs 2.6.3 schema warning as wave 1).</td></tr><tr><td><code>pnpm exec prettier --check &lt;scope&gt;</code></td><td>All files formatted.</td></tr><tr><td><code>node scripts/check-jsdoc.mts</code></td><td>Pass, no new exports without JSDoc.</td></tr><tr><td><code>node scripts/check-unicode-escapes.mts</code></td><td>Pass, 2315 files.</td></tr><tr><td><code>node scripts/check-american-filenames.mts</code></td><td>Pass.</td></tr><tr><td><code>pnpm --filter server --filter console --filter prismarine run typecheck</code></td><td>Pass.</td></tr><tr><td><code>pnpm exec vitest run packages/server/src packages/prismarine/src/console packages/console/src</code></td><td>30 files, 304 tests pass on Node 26.12.1.</td></tr></tbody></table><p>Nothing in scope fails <code>pnpm run lint</code> or <code>pnpm run typecheck</code>.</p><h2 id="counts" tabindex="-1">Counts <a class="header-anchor" href="#counts" aria-label="Permalink to “Counts”">​</a></h2><p>Bug 5, design 7, nit 10, lint failure 0.</p><h2 id="findings-by-owner" tabindex="-1">Findings by owner <a class="header-anchor" href="#findings-by-owner" aria-label="Permalink to “Findings by owner”">​</a></h2><h3 id="server-host-packages-server-src-server-ts-cli-host" tabindex="-1">Server host (<code>packages/server/src/Server.ts</code>, <code>cli/</code>, <code>host/</code>) <a class="header-anchor" href="#server-host-packages-server-src-server-ts-cli-host" aria-label="Permalink to “Server host (packages/server/src/Server.ts, cli/, host/)”">​</a></h3><ol><li><strong>bug</strong>, <code>packages/server/src/host/ServerChild.ts:129-137</code>. The child is declared gone on <code>&#39;exit&#39;</code>, but a spawn that fails (<code>EAGAIN</code>, <code>EMFILE</code>, a bad <code>execPath</code>) emits <code>&#39;error&#39;</code> and <code>&#39;close&#39;</code> and never <code>&#39;exit&#39;</code> (verified on Node 26.12: <code>error ENOENT</code>, <code>close -2 null</code>, no <code>exit</code>). The comment says both end in <code>&#39;exit&#39;</code>; they do not. <code>Supervisor.start</code> then sits in <code>starting</code> with a dead <code>child</code>, <code>stop()</code> arms SIGTERM and SIGKILL against a process that never existed, and the host never exits. Fix: listen on <code>&#39;close&#39;</code> (fires in both cases) and report <code>code ?? 1</code>; <code>subprocessLink</code> in the protocol package has the same <code>&#39;exit&#39;</code> dependency and should move to <code>&#39;close&#39;</code> too.</li><li><strong>bug</strong>, <code>packages/server/src/host/Supervisor.ts:101</code>. <code>await this.options.spawnChild()</code> has no catch. A rejection (for instance <code>import(&#39;node:sea&#39;)</code> failing) leaves <code>spawning = true</code> forever, so <code>start</code>, <code>restart</code>, and <code>stop</code> all become no-ops and the host hangs in <code>starting</code>. Fix: wrap in try/catch, reset <code>spawning</code>, and either <code>setState(&#39;crashed&#39;)</code> then <code>waiting</code> under <code>--watch</code> or <code>exit(1)</code> otherwise; add a test with a rejecting <code>spawnChild</code>.</li><li><strong>bug</strong> (Windows), <code>packages/server/src/host/Watcher.ts:151</code> and <code>packages/server/src/host/ServerChild.ts:101,163</code>. <code>spawnSync(&#39;pnpm&#39;, ...)</code> without <code>shell: true</code> fails with <code>ENOENT</code> on Windows (<code>pnpm.cmd</code>), so every <code>--watch</code> start reports <code>bedrock-data generation failed</code>; and <code>child.kill(&#39;SIGTERM&#39;)</code> on Windows is an unconditional terminate, so a graceful shutdown that takes longer than <code>shutdownGraceMs</code> (1 s) is cut off before the world saves. Fix: <code>process.platform === &#39;win32&#39; ? &#39;pnpm.cmd&#39; : &#39;pnpm&#39;</code> (or <code>shell: true</code>), and on win32 skip the SIGTERM step and give the <code>shutdown</code> message the full <code>killGraceMs</code> before SIGKILL.</li><li><strong>design</strong>, <code>packages/server/src/host/Watcher.ts:138-145,123</code> and <code>packages/server/src/Server.ts:127-138</code>. Generation runs through <code>spawnSync</code>, which blocks the host event loop: in TUI mode the renderer freezes, the <code>generating</code> toast cannot paint until the generator has finished, keypresses and child IPC messages queue up, and because <code>ui.attach</code> runs before <code>watcher.start()</code>, the first thing the user sees is a frozen screen for the length of a <code>pnpm</code> startup. The <code>if (this.generating) return</code> guard in <code>requestRestart</code> is unreachable for the same reason: a synchronous generator can never be observed mid-run. Fix: use async <code>spawn</code>, keep <code>generating</code> true across the await (which makes the guard real), and hold the debounce timers while it runs; or at least run the initial generation before <code>ui.attach</code>.</li><li><strong>design</strong>, <code>packages/server/src/host/Supervisor.ts:198-199</code> and <code>packages/console/src/app/createApp.ts:433-490</code>. After a crash the supervisor always goes <code>crashed</code> then <code>waiting</code>, but without <code>--watch</code> nothing will ever restart it: no watcher is attached, <code>actions.restart</code> is never called from <code>createApp</code>, and the catalog has no <code>server.restart</code> entry. The only way out is Ctrl+C twice, which calls <code>stop()</code> with no child and exits 0, losing the crash code the wrappers were promised. Fix: give <code>Supervisor</code> a <code>canRestart</code> flag (true only when a watcher is attached) and treat a crash as <code>stopped</code> with the child&#39;s code when it is false; and add <code>server.restart</code> (Ctrl+Shift+R or the palette) so a TUI user can restart a crashed server under <code>--watch</code> without saving a file.</li><li><strong>design</strong>, <code>packages/server/src/Server.ts:115-139</code> and <code>packages/console/src/startConsole.ts:142-146</code>. The host has no fatal path of its own. In plain mode an uncaught exception (an <code>EPIPE</code> on stdout under <code>| head</code> is enough) takes Node&#39;s default exit; in TUI mode <code>onUncaught</code> restores the terminal and calls <code>process.exit(1)</code>. Neither tells the supervisor, so the child is left to notice the IPC disconnect and run a full graceful shutdown with no SIGTERM or SIGKILL backstop; a child stuck in shutdown is an orphan. Fix: in <code>runHost</code>, register <code>uncaughtException</code> and <code>unhandledRejection</code> handlers that call <code>ui.close()</code> (best effort), then <code>supervisor.forceStop()</code> or <code>child.stop()</code>, then exit 1; let <code>startConsole</code> keep only the terminal restore and leave exiting to the host.</li><li><strong>nit</strong>, <code>packages/server/src/host/Supervisor.ts:192-194</code>. A child killed by a signal with no stop requested (<code>code === null</code>, <code>forced === false</code>) exits the host with <code>code ?? 0</code>, so an OOM kill or SIGSEGV reads as success to a wrapper. Fix: <code>code ?? 1</code>, or <code>128 + signo</code> to match the shell convention.</li><li><strong>nit</strong>, <code>packages/server/src/Server.ts:121-124</code>. <code>exit</code> awaits <code>ui.close()</code> before <code>process.exit(code)</code>; a rejected close (a failed history save is swallowed, but a renderer <code>destroy</code> throw is not) means the host never exits. Fix: <code>try { await ui.close() } finally { process.exit(code) }</code>.</li><li><strong>nit</strong>, <code>packages/server/src/Server.ts:173</code> and <code>packages/server/src/cli/Cli.ts:48-55</code>. <code>--watch --headless</code> silently drops <code>--watch</code>. Fix: reject the combination in the <code>check</code> callback with a message, or run the host headless with the watcher and no frontend.</li><li><strong>nit</strong>, <code>packages/server/src/Server.ts:130</code>. <code>packagesDir</code> is derived from <code>import.meta.url</code> with <code>../..</code>, which is <code>packages/</code> for both <code>src/Server.ts</code> and <code>dist/Server.es.js</code> in the monorepo but <code>node_modules/@jsprismarine/</code> for an installed package, where it watches nothing and <code>pnpm run generate</code> fails on every start. Fix: require <code>pnpm-workspace.yaml</code> next to <code>packagesDir</code> and print one line (<code>--watch needs the JSPrismarine repository</code>) otherwise.</li><li><strong>nit</strong>, <code>packages/server/src/Server.ts:68</code> with <code>packages/logger/src/logger.ts:26,39</code>. The headless child still gets the default <code>PrismarineTransport</code>, which buffers its last 1000 records for a console that never attaches. Harmless but pointless. Fix: a <code>Logger</code> option to omit the console transport, set when <code>headless</code>.</li></ol><h3 id="prismarine-remote-console-packages-prismarine-src-console-server-ts-wiring" tabindex="-1">Prismarine remote console (<code>packages/prismarine/src/console/</code>, <code>Server.ts</code> wiring) <a class="header-anchor" href="#prismarine-remote-console-packages-prismarine-src-console-server-ts-wiring" aria-label="Permalink to “Prismarine remote console (packages/prismarine/src/console/, Server.ts wiring)”">​</a></h3><ol start="12"><li><strong>bug</strong>, <code>packages/prismarine/src/console/RemoteConsole.ts:156-165</code> with <code>packages/prismarine/src/command/vanilla/StopCommand.ts:20</code> and <code>packages/console/src/startConsole.ts:229-232</code>. <code>StopCommand</code> awaits <code>server.shutdown()</code>, which ends in <code>process.exit</code>, so <code>dispatchCommand</code> never resolves and <code>command.result</code> is never sent. On the host the link closes first, <code>failPending(&#39;server link closed&#39;)</code> rejects the request, and <code>createApp.submit</code> shows a danger toast for a <code>stop</code> that worked. The same happens for any command that stops the server. Fix: in <code>RemoteConsole.runCommand</code>, answer <code>{ ok: true }</code> when the dispatch is still pending as <code>disable()</code> runs (track in flight ids and flush them in <code>disable</code>); or in <code>startConsole.onCommand</code>, treat a <code>server link closed</code> rejection as <code>{ ok: true }</code> while the supervisor state is <code>stopping</code>.</li><li><strong>design</strong>, <code>packages/prismarine/src/console/RemoteConsole.ts:180-182</code> with <code>packages/prismarine/src/Server.ts:546-548</code>. <code>tickMs: 1000 / tps</code> restates TPS, so the <code>tick 50 ms</code> segment reads healthy at any load short of a dropped tick; the tick loop measures <code>elapsedMs</code> for every tick and throws it away. Fix: keep a short EMA of <code>elapsedMs</code> on the server and expose <code>getTickMs()</code>, then send that; until then drop <code>tickMs</code> from the status rather than send a derived number the status bar labels as a measurement.</li><li><strong>nit</strong>, <code>packages/prismarine/src/console/RemoteConsole.ts:25-26</code>. The coalescing key uses <code>getTPS()</code> at two decimals, which on a live server moves every second (<code>19.98</code>, <code>20.02</code>), so the &quot;only while something changed or every 5 s&quot; rule degrades to 1 Hz always. Fix: round TPS to the nearest 0.5 (or integer) in <code>statusKey</code>.</li><li><strong>nit</strong>, <code>packages/prismarine/src/console/RemoteConsole.ts:84-85</code>. <code>link.onClose</code> is subscribed in <code>enable()</code>, which runs after <code>childProcessLink</code>&#39;s born-closed microtask unless the whole <code>runInProcess -&gt; bootstrap -&gt; enable</code> chain stays synchronous (it does today; one <code>await</code> added before <code>remoteConsole.enable()</code> in <code>Server.bootstrap</code> breaks it). Fix: subscribe in the constructor like <code>RemoteLogTransport</code> does.</li></ol><h3 id="console-app-packages-console-src-app-help-startconsole-ts" tabindex="-1">Console app (<code>packages/console/src/{app,help,startConsole.ts}</code>) <a class="header-anchor" href="#console-app-packages-console-src-app-help-startconsole-ts" aria-label="Permalink to “Console app (packages/console/src/{app,help,startConsole.ts})”">​</a></h3><ol start="16"><li><strong>bug</strong>, <code>packages/console/src/startConsole.ts:68</code>. <code>TERMINAL_RESET</code> leaves the alternate screen and turns mouse and bracketed paste off, but OpenTUI&#39;s native <code>setupTerminal</code> also pushes kitty keyboard flags (<code>useKittyKeyboard</code> defaults to <code>{}</code>, which <code>buildKittyKeyboardFlags</code> turns into disambiguate and alternate keys). After a host crash the shell receives kitty-encoded keys until the user runs <code>reset</code>. Fix: append <code>\\x1b[&lt;u</code> (pop kitty flags), <code>\\x1b[?1004l</code> (focus events), <code>\\x1b[?2026l</code> (synchronized output), and <code>\\x1b[0m</code>, and add a test that the sequence contains the kitty pop.</li><li><strong>design</strong>, <code>packages/console/src/app/createApp.ts:362-382</code> with <code>packages/prismarine/src/command/CommandManager.ts:260</code>. <code>localCommand</code> claims every line beginning with <code>/</code> for search and namespace filters, but the server strips a leading <code>/</code> and the line console accepted <code>/stop</code>, <code>/list</code>, and <code>/say</code> the way Bedrock players type them. A user who types <code>/stop</code> now searches the log for &quot;stop&quot;. Fix: route <code>/name ...</code> to the server when <code>name</code> is a known command (the completion list already has the names), or move the local commands to a prefix the server does not use (<code>:</code> or <code>/log</code>).</li><li><strong>design</strong>, <code>packages/console/src/startConsole.ts:147-148</code>. Only <code>uncaughtException</code> gets the terminal-restore fallback. OpenTUI registers <code>unhandledRejection -&gt; console.error</code>, and with <code>consoleMode: &#39;disabled&#39;</code> that output goes nowhere, so a rejected promise in the host (there is no <code>--unhandled-rejections=strict</code> on the <code>dev</code> script) disappears without a toast or an exit. Fix: register the same handler for <code>unhandledRejection</code>, or route it through <code>report()</code> so it becomes a sticky toast.</li><li><strong>nit</strong>, <code>packages/console/src/app/createApp.ts:396-409</code> and <code>packages/console/src/input/keys.ts:66-70</code>. The plan says a Ctrl+C while the server is <code>stopping</code> force kills; the decoder escalates by press count within a 2 s window and knows nothing of the state, so a user who waits more than 2 s after the stop needs three presses (hint, no-op stop, force). Fix: pass <code>serverStopping: state === &#39;stopping&#39;</code> into <code>KeyState</code> and return <code>force</code> on the first press when it is set.</li></ol><h3 id="changesets-and-manifests" tabindex="-1">Changesets and manifests <a class="header-anchor" href="#changesets-and-manifests" aria-label="Permalink to “Changesets and manifests”">​</a></h3><ol start="20"><li><strong>nit</strong>, <code>.changeset/hosts-watch-terminals.md:5</code> and <code>.changeset/new-console-packages.md:6</code>. Both say the TUI runs &quot;on Node 26.4 or newer&quot;, but the gate is <code>await import(&#39;node:ffi&#39;)</code>, which 26.4 to 26.8 only pass with <code>--experimental-ffi</code>. Say &quot;on a Node that loads <code>node:ffi</code> (26.9 and later, or 26.4 and later with <code>--experimental-ffi</code>)&quot;.</li><li><strong>nit</strong>, <code>.changeset/new-console-packages.md</code>. Judge 2 asked for the exact <code>@opentui/core</code> pin to be recorded in a changeset note; add &quot;pins <code>@opentui/core</code> 0.6.8 exactly&quot;.</li><li><strong>design</strong>, <code>packages/server/package.json:84</code> with <code>packages/console/package.json</code> (<code>engines.node &gt;=26.4.0</code>). <code>@jsprismarine/console</code> is a hard dependency of <code>@jsprismarine/server</code> (root engines <code>&gt;=22.18.0</code>), so installing the server on Node 22 pulls <code>@opentui/core</code> and its eight platform binaries and trips npm&#39;s engine warning for a package the plain path never imports. The changeset&#39;s &quot;everywhere else ... unchanged&quot; is not quite true of install. Fix: make it an <code>optionalDependencies</code> entry (the lazy import already tolerates its absence once <code>loadTuiFrontend</code> catches the import error), and say so in the changeset.</li></ol><p>Bump levels check out against <code>docs/guide/versioning.md</code>: server, console, console-protocol, and logger are additive at 0.x and take <code>patch</code>; prismarine removes <code>writeAbovePrompt</code> and <code>PromptWriter</code> and takes <code>minor</code>. The logger changeset names <code>LOG_LEVELS</code>, <code>isLogLevel</code>, and <code>isAtLeastLevel</code>. The flags in <code>hosts-watch-terminals.md</code> (<code>--watch</code>, <code>--no-tui</code>, <code>--headless</code>, <code>JSP_NO_TUI</code>) match <code>Cli.ts</code> and <code>tuiGate.ts</code>, and <code>Dockerfile:21</code> sets <code>ENV JSP_NO_TUI=1</code>.</p><h2 id="not-findings-checked" tabindex="-1">Not findings, checked <a class="header-anchor" href="#not-findings-checked" aria-label="Permalink to “Not findings, checked”">​</a></h2><ul><li><code>startConsole.attach</code> detaches the previous generation&#39;s <code>onMessage</code> and <code>onClose</code> before subscribing the next, and <code>close()</code> detaches the last one; no listener leak per generation. The 10 s request timers are cleared on answer, on link close (<code>failPending</code>), and on close.</li><li>Handler ordering: OpenTUI&#39;s <code>uncaughtException</code> handler only <code>console.error</code>s and does not exit, so <code>startConsole</code>&#39;s handler, registered after it, runs and exits. Global <code>keyInput</code> listeners run before renderable handlers in OpenTUI&#39;s <code>emit</code>, so <code>createApp.onKey</code> resolves catalog bindings and <code>preventDefault</code>s before the <code>InputRenderable</code> inserts the character; <code>n</code>, <code>N</code>, Home, and End on an empty line work as bound.</li><li><code>forceStop</code> reaches <code>SIGKILL</code> through <code>child.kill()</code>; <code>handleSignals</code> maps the second signal to it; <code>stop</code> escalates <code>shutdown</code> message, SIGTERM at 1 s, SIGKILL at 11 s.</li><li>Crash during <code>stopping</code> exits with the child&#39;s code; restart requested while spawning stops the fresh child and spawns again (correct for a file saved mid-spawn); SIGINT twice in plain mode is handled consistently by both processes (the child&#39;s second press exits 1, the host&#39;s second press kills).</li><li><code>loadEnvFiles</code> runs in both processes against the same <code>cwd</code> and the host passes its mutated <code>process.env</code> to the child; <code>JSP_DIR</code> resolves identically. <code>--watch</code> under <code>dist/</code> resolves <code>packagesDir</code> to <code>packages/</code>.</li><li>Double output: the child writes no log lines to its own stdout (the logger has no console attached and nothing falls back to stdout); the only raw lines are <code>console.debug(&#39;Server stopped, Goodbye!&#39;)</code> and <code>console.error</code> from <code>Server.shutdown</code>, which surface as raw <code>supervisor.output</code> lines as judge 2 asked.</li><li><code>RemoteLogTransport</code> now subscribes to <code>link.onClose</code> (wave 1 finding 7 landed), and <code>childProcessLink</code> reports a born-closed channel (wave 1 finding 3 landed).</li></ul></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};